      END_STATE();
    case 189:
      if (lookahead == 'e') ADVANCE(192);
      END_STATE();
    case 190:
      if (lookahead == 'l') ADVANCE(193);
      END_STATE();
    case 191:
      if (lookahead == 'e') ADVANCE(194);
      END_STATE();
    case 192:
